<script setup lang="ts">
import { useApi } from '~/composables/useApi';

import type { PriceSummary, PriceComparison } from '~/types/api'
import { money,numberTR,dateTR } from '~/utils/format'
const api=useApi();const propertyType=ref('apartment');const areaType=ref('net');const minPrice=ref('');const maxPrice=ref('');const minNet=ref('');const maxNet=ref('');const minGross=ref('');const maxGross=ref('');const minParcel=ref('');const maxParcel=ref('');const rooms=ref('');const minAge=ref('');const maxAge=ref('');const province=ref('');const district=ref('');const neighborhood=ref('');const zoningStatus=ref('');const zoningUse=ref('');const threshold=ref(5);const summary=ref<PriceSummary|null>(null);const comparison=ref<PriceComparison|null>(null);const state=ref<'idle'|'loading'|'error'|'success'>('idle');const error=ref('')
const route=useRoute()
onMounted(()=>{const q=route.query;const get=(key:string)=>{const v=q[key];return Array.isArray(v)?String(v[0]??''):String(v??'')};if(get('property_type'))propertyType.value=get('property_type');if(get('area_type'))areaType.value=get('area_type');if(get('min_price'))minPrice.value=get('min_price');if(get('max_price'))maxPrice.value=get('max_price');if(get('min_net_area_m2'))minNet.value=get('min_net_area_m2');if(get('max_net_area_m2'))maxNet.value=get('max_net_area_m2');if(get('min_gross_area_m2'))minGross.value=get('min_gross_area_m2');if(get('max_gross_area_m2'))maxGross.value=get('max_gross_area_m2');if(get('min_parcel_area_m2'))minParcel.value=get('min_parcel_area_m2');if(get('max_parcel_area_m2'))maxParcel.value=get('max_parcel_area_m2');if(get('room_count'))rooms.value=get('room_count');if(get('min_building_age'))minAge.value=get('min_building_age');if(get('max_building_age'))maxAge.value=get('max_building_age');if(get('province_id'))province.value=get('province_id');if(get('district_id'))district.value=get('district_id');if(get('neighborhood_id'))neighborhood.value=get('neighborhood_id');if(get('zoning_status'))zoningStatus.value=get('zoning_status');if(get('zoning_use'))zoningUse.value=get('zoning_use');if(get('minimum_listings'))threshold.value=Number(get('minimum_listings'))})
const residential=computed(()=>['apartment','detached_house','villa'].includes(propertyType.value));const land=computed(()=>['residential_land','commercial_land','farmland'].includes(propertyType.value));const filters=computed(()=>({property_type:propertyType.value,area_type:areaType.value,minimum_listings:threshold.value,min_price:minPrice.value||undefined,max_price:maxPrice.value||undefined,min_net_area_m2:residential.value?minNet.value||undefined:undefined,max_net_area_m2:residential.value?maxNet.value||undefined:undefined,min_gross_area_m2:residential.value?minGross.value||undefined:undefined,max_gross_area_m2:residential.value?maxGross.value||undefined:undefined,min_parcel_area_m2:land.value?minParcel.value||undefined:undefined,max_parcel_area_m2:land.value?maxParcel.value||undefined:undefined,room_count:residential.value?rooms.value||undefined:undefined,min_building_age:residential.value?minAge.value||undefined:undefined,max_building_age:residential.value?maxAge.value||undefined:undefined,province_id:province.value||undefined,district_id:district.value||undefined,neighborhood_id:neighborhood.value||undefined,zoning_status:propertyType.value==='residential_land'?zoningStatus.value||undefined:undefined,zoning_use:propertyType.value==='residential_land'?zoningUse.value||undefined:undefined}))
async function run(){state.value='loading';error.value='';try{const s=await api.priceSummary(filters.value as Record<string,string|number|undefined>);summary.value=s;const groupBy=residential.value?(rooms.value?'room_count':minAge.value||maxAge.value?'building_age':'area_band'):propertyType.value==='residential_land'&&zoningStatus.value?'zoning_status':'area_band';comparison.value=await api.compare({...filters.value,group_by:groupBy} as Record<string,string|number|undefined>);state.value='success'}catch(e){state.value='error';error.value=e instanceof Error?e.message:'Analiz çalıştırılamadı.'}}
function saveFilter(){if(!import.meta.client)return;const name=window.prompt('Bu filtreye bir ad verin:');if(!name?.trim())return;try{const saved=JSON.parse(localStorage.getItem('rea-saved-filters')||'[]') as Array<{name:string;filters:Record<string,unknown>;createdAt:string}>;saved.unshift({name:name.trim(),filters:filters.value as unknown as Record<string,unknown>,createdAt:new Date().toISOString()});localStorage.setItem('rea-saved-filters',JSON.stringify(saved));alert('Filtre bu tarayıcıya kaydedildi.')}catch{alert('Filtre kaydedilemedi.')}}
</script>
<template><div class="page-heading"><div><p class="eyebrow">ANALİZ ARAÇLARI</p><h1>Gelişmiş filtreleme</h1><p>Gayrimenkul türüne uygun özellikleri seçin. Sorgu, yalnızca API'den dönen verilerle analiz edilir.</p></div><div class="heading-actions"><button class="button button-secondary" @click="saveFilter">☆ Filtreyi kaydet</button><button class="button button-primary" @click="run">Analiz et →</button></div></div><section class="filter-card"><div class="filter-grid"><div class="field"><label>Gayrimenkul türü</label><select v-model="propertyType"><option value="apartment">Daire</option><option value="detached_house">Müstakil ev</option><option value="villa">Villa</option><option value="residential_land">İmarlı arsa</option><option value="commercial_land">Ticari arsa</option><option value="farmland">Tarla</option></select></div><div class="field"><label>Minimum fiyat (₺)</label><input v-model="minPrice" type="number" min="0"/></div><div class="field"><label>Maksimum fiyat (₺)</label><input v-model="maxPrice" type="number" min="0"/></div><div class="field"><label>İl ID</label><input v-model="province" type="number" min="1"/></div><div class="field"><label>İlçe ID</label><input v-model="district" type="number" min="1"/></div><div class="field"><label>Mahalle ID</label><input v-model="neighborhood" type="number" min="1"/></div><div class="field"><label>Minimum ilan eşiği</label><input v-model.number="threshold" type="number" min="1" max="100"/></div><template v-if="residential"><h2 class="form-section-title">Konut özellikleri</h2><div class="field"><label>Net alan aralığı (m²)</label><div class="field-row"><input v-model="minNet" type="number" min="0.01" placeholder="Min"/><input v-model="maxNet" type="number" min="0.01" placeholder="Maks"/></div></div><div class="field"><label>Brüt alan aralığı (m²)</label><div class="field-row"><input v-model="minGross" type="number" min="0.01" placeholder="Min"/><input v-model="maxGross" type="number" min="0.01" placeholder="Maks"/></div></div><div class="field"><label>Oda sayısı</label><select v-model="rooms"><option value="">Tümü</option><option v-for="r in [1,2,3,4,5,6,7,8]" :key="r" :value="String(r)">{{ r }} oda ({{ r>1 ? (r-1)+'+1' : '1+0' }})</option></select></div><div class="field"><label>Bina yaşı aralığı</label><div class="field-row"><input v-model="minAge" type="number" min="0" placeholder="Min"/><input v-model="maxAge" type="number" min="0" placeholder="Maks"/></div></div></template><template v-if="land"><h2 class="form-section-title">Arazi özellikleri</h2><div class="field"><label>Parsel alanı aralığı (m²)</label><div class="field-row"><input v-model="minParcel" type="number" min="0.01" placeholder="Min"/><input v-model="maxParcel" type="number" min="0.01" placeholder="Maks"/></div></div><div v-if="propertyType==='residential_land'" class="field"><label>İmar durumu</label><select v-model="zoningStatus"><option value="">Tüm durumlar</option><option value="zoned">İmarlı</option><option value="unzoned">İmarsız</option><option value="partially_zoned">Kısmen imarlı</option></select></div><div v-if="propertyType==='residential_land'" class="field"><label>İmar kullanım amacı</label><select v-model="zoningUse"><option value="">Tümü</option><option value="residential">Konut</option><option value="commercial">Ticari</option><option value="mixed">Karma</option><option value="industrial">Sanayi</option></select></div></template></div><div class="filter-actions"><span class="muted">Eksik özellikler bilinmiyor olarak kalır; net/brüt/parsel alanı birbirine karışmaz.</span><div><button class="button button-secondary" @click="minPrice='';maxPrice='';minNet='';maxNet='';minGross='';maxGross='';minParcel='';maxParcel='';rooms='';minAge='';maxAge='';province='';district='';neighborhood='';zoningStatus='';zoningUse='';summary=null;comparison=null;state='idle'">Temizle</button><button class="button button-primary" @click="run">Sonuçları getir →</button></div></div></section><div v-if="state==='success'&&summary?.reliability==='limited'" class="alert alert-warning">{{ summary.reliability_note }}</div><section class="panel"><div class="panel-header"><div><h2>Filtre sonuçları</h2><p>Özet ve karşılaştırma değerleri gerçek API yanıtından üretilir.</p></div></div><StatePanel v-if="state==='idle'" state="empty" message="Filtreleri seçip analiz çalıştırın."/><StatePanel v-else-if="state==='loading'" state="loading"/><StatePanel v-else-if="state==='error'" state="error" :message="error" @retry="run"/><template v-else-if="summary"><div class="metric-grid"><MetricCard label="İlan sayısı" :value="numberTR(summary.listing_count)"/><MetricCard label="Ortalama fiyat" :value="money(summary.average_asking_price)"/><MetricCard label="Medyan fiyat" :value="money(summary.median_asking_price)"/><MetricCard label="Son veri güncellemesi" :value="dateTR(summary.last_data_updated_at)"/></div><div class="table-wrap"><table><thead><tr><th>Grup</th><th>İlan sayısı</th><th>Ortalama fiyat</th><th>Medyan fiyat</th><th>Ortalama m² fiyatı</th><th>Alan türü</th></tr></thead><tbody><tr v-for="g in comparison?.groups||[]" :key="g.group_key"><td class="table-primary">{{ g.group_label }}</td><td>{{ numberTR(g.listing_count) }}</td><td>{{ money(g.average_asking_price) }}</td><td>{{ money(g.median_asking_price) }}</td><td>{{ money(g.average_price_per_m2) }}</td><td>{{ g.area_type||'—' }}</td></tr></tbody></table></div><p class="panel-footnote">{{ summary.price_basis }} {{ summary.reliability_note }}</p></template></section></template>

